// All packet types
pub enum MqttPacket { Connect(ConnectPacket), Connack(ConnackPacket), Publish(PublishPacket), Puback(PubackPacket), Pubrec(PubrecPacket), Pubrel(PubrelPacket), Pubcomp(PubcompPacket), Subscribe(SubscribePacket), Suback(SubackPacket), Unsubscribe(UnsubscribePacket), Unsuback(UnsubackPacket), Pingreq, Pingresp, Disconnect,
} // Decoder
pub struct MqttDecoder;
impl MqttDecoder { pub fn decode(bytes: &mut BytesMut) -> Result<Option<MqttPacket>>;
} // Encoder
pub struct MqttEncoder;
impl MqttEncoder { pub fn encode(packet: &MqttPacket, buf: &mut BytesMut) -> Result<()>;
}

